<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Time off · IT Master Tool</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:wght@400;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="/app.css">
<link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>🏖️</text></svg>">
</head>
<body data-page="timeoff">
<div class="wrap">
  <header class="top">
    <div>
      <h1>IT time off</h1>
      <p>PTO balances, the time off log, and who can sign in. <span class="who-am-i" id="whoami"></span></p>
    </div>
    <div class="actions">
      <select id="yearSel" class="yr" aria-label="PTO year"></select>
      <button class="btn" id="addEmpBtn" type="button">Add team member</button>
      <button class="btn primary" id="logBtn" type="button">Log time off</button>
    </div>
    <div class="top-alert-wrap"><button class="btn top-alert" id="topAlert" type="button" hidden><span aria-hidden="true">🔔</span> <span id="topAlertText"></span></button></div>
  </header>

  <nav class="tabs page-tabs" aria-label="Sections">
    <a href="/" id="navSched" class="ptab">Schedule</a>
    <a href="/timeoff/" id="navTimeoff" class="ptab" aria-current="page">Time off</a>
    <a href="/projects/" id="navProj" class="ptab">Projects</a>
    <a href="/inventory/" id="navInv" class="ptab">Inventory</a>
    <a href="/newhires/" id="navHire" class="ptab">New Hires</a>
  </nav>

  <div class="notice" id="notice" hidden></div>

    <section class="panel pin-gate" id="ptoGate" hidden>
      <div class="ic" aria-hidden="true">🔒</div>
      <h2>Time off is locked</h2>
      <p>Choose your name and enter your 4-digit PIN. Team members see only their own time off.</p>
      <form id="ptoGateForm" class="gate-form" autocomplete="off">
        <select id="ptoWho" aria-label="Your name"></select>
        <input id="ptoPin" type="password" inputmode="numeric" maxlength="4" placeholder="PIN" aria-label="4-digit PIN">
        <button class="btn primary" type="submit">Unlock</button>
      </form>
      <div class="err" id="ptoGateErr" role="alert"></div>
    </section>
  <section class="panel lock" id="lockPanel">
      <div class="ic" aria-hidden="true">🔒</div>
      <h2 id="lockTitle">Checking your access…</h2>
      <p id="lockMsg"></p>
    </section>
  <div id="ptoContent" hidden>
    <div class="pto-viewer" id="ptoViewerBar"><span id="ptoViewerText"></span><span class="actions"><button class="btn small primary" id="rtoOpen" type="button">📝 RTO</button><button class="btn small" id="ptoLockBtn" type="button">🔒 Lock</button></span></div>
  <section class="panel" aria-labelledby="balH">
      <div class="panel-head">
        <h2 id="balH">PTO balances</h2>
        <div class="actions"><span class="emp-role" id="balNote"></span><button class="btn" id="addEmpBtn2" type="button">Add team member</button></div>
      </div>
      <div class="scroll" id="balances"></div>
    </section>

  <section class="panel" aria-labelledby="calH">
      <div class="panel-head">
        <h2 id="calH">Coverage calendar</h2>
        <div class="cal-nav">
          <button class="btn ghost" id="prevM" type="button" aria-label="Previous month">‹</button>
          <strong id="calLabel"></strong>
          <button class="btn ghost" id="nextM" type="button" aria-label="Next month">›</button>
          <button class="btn" id="thisM" type="button">Today</button>
        </div>
      </div>
      <div class="scroll"><div class="cal" id="cal"></div></div>
      <div class="legend">
        <span class="t-Vacation"><i></i><span style="color:var(--muted)">Vacation</span></span>
        <span class="t-Sick"><i></i><span style="color:var(--muted)">Sick</span></span>
        <span class="t-CalledOut"><i></i><span style="color:var(--muted)">Called Out</span></span>
        <span class="t-Personal"><i></i><span style="color:var(--muted)">Personal</span></span>
        <span class="t-Other"><i></i><span style="color:var(--muted)">Other</span></span>
        <span>Red count = 3 or more people out that day</span>
      </div>
    </section>

  <section class="panel" aria-labelledby="logH">
      <div class="panel-head">
        <h2 id="logH">Time off log</h2>
        <div class="filters">
          <select id="fEmp" aria-label="Filter by team member"><option value="">Everyone</option></select>
          <select id="fType" aria-label="Filter by type">
            <option value="">All types</option><option>Vacation</option><option>Sick</option><option>Called Out</option><option>Personal</option><option>Other</option>
          </select>
          <button class="btn" id="csvBtn" type="button">Export CSV</button>
          <button class="btn primary" id="logForBtn" type="button">Log time off</button>
        </div>
      </div>
      <div class="scroll" id="log"></div>
    </section>

    <section class="panel" aria-labelledby="ntH">
      <div class="panel-head">
        <h2 id="ntH">Email notifications</h2>
        <button class="btn" id="testMailBtn" type="button">Send test email</button>
      </div>
      <p id="notifyInfo" style="margin:0;padding:14px 18px;color:var(--muted)">Checking…</p>
    </section>

    <section class="panel" aria-labelledby="lgH">
      <div class="panel-head">
        <h2 id="lgH">Who can sign in</h2>
        <button class="btn primary" id="addLoginBtn" type="button">Add a person</button>
      </div>
      <div class="scroll" id="logins"></div>
      <div class="foot-note">People sign in with their Microsoft 365 work account. Only people listed here can get in, even within Lester Glenn. Managers can open Time Off; staff see the IT Schedule only.</div>
    </section>
  </div>
</div>

<dialog id="empDlg">
  <form method="dialog" id="empForm">
    <h3 id="empTitle">Add team member</h3>
    <div class="field"><label for="eName">Name</label><input id="eName" required maxlength="80" autocomplete="off"></div>
    <div class="field"><label for="eRole">Role</label><input id="eRole" maxlength="80" placeholder="e.g. Help desk, Network admin" autocomplete="off"></div>
    <div class="field"><label for="eLoc">Starting location</label><select id="eLoc"><option value="">Not set</option><option>Lester Glenn Mazda of Toms River</option><option>Lester Glenn Hyundai of Toms River</option><option>Lester Glenn Chevy of Toms River</option><option>Lester Glenn GMC of Toms River</option><option>Lester Glenn Subaru of Toms River</option><option>Lester Glenn Collision of Toms River</option><option>Lester Glenn Chrysler of Toms River</option><option>Lester Glenn Honda of Sea Girt</option><option>Lester Glenn Ford of Ocean</option><option>Lester Glenn Chevy of Freehold</option><option>Lester Glenn Chevy of Old Bridge</option><option>Lester Glenn Corporate of Toms River</option><option>Lester Glenn Warranty of Toms River</option><option>Lester Glenn Service BDC of Toms River</option><option>Lester Glenn Marketing</option><option>Lester Glenn Used Car Dept</option><option>Remote</option></select>
      <small>Where they usually start their day. You can change it for a single day from the weekly schedule.</small></div>
    <div class="field" id="ePinField" hidden><label for="ePin">4-digit PIN for inventory</label><input id="ePin" type="password" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" autocomplete="new-password" placeholder="••••"><small id="ePinNote"></small></div>
    <div class="field" id="allowField"><label for="eAllow">Annual PTO allowance (days)</label><input id="eAllow" type="number" min="0" max="365" step="0.5" value="15" required></div>
    <fieldset>
      <legend>Regular hours</legend>
      <div id="eHours"></div>
      <button class="btn small" id="copyMon" type="button">Copy Monday's hours to Tue–Fri</button>
    </fieldset>
    <div class="err" id="empErr"></div>
    <div class="dlg-actions">
      <button class="btn danger" id="empDel" type="button" hidden>Remove</button>
      <div class="right">
        <button class="btn ghost" value="cancel" formnovalidate>Cancel</button>
        <button class="btn primary" id="empSave" value="save">Save team member</button>
      </div>
    </div>
  </form>
</dialog>

<dialog id="logDlg">
  <form method="dialog" id="logForm">
    <h3 id="logTitle">Log time off</h3>
    <div class="field"><label for="lEmp">Team member</label><select id="lEmp" required></select></div>
    <div class="field"><label for="lType">Type</label>
      <select id="lType"><option>Vacation</option><option>Sick</option><option>Called Out</option><option>Personal</option><option>Other</option></select></div>
    <div class="row2">
      <div class="field"><label for="lStart">First day off</label><input id="lStart" type="date" required></div>
      <div class="field"><label for="lEnd">Last day off</label><input id="lEnd" type="date" required></div>
    </div>
    <div class="field"><label for="lDays">Days charged</label><input id="lDays" type="number" min="0.5" step="0.5" required>
      <small>Counts weekdays automatically. Use 0.5 for a half day.</small></div>
    <div class="warn" id="overlap" hidden></div>
    <div class="field"><label for="lNote">Note (optional)</label><input id="lNote" maxlength="200" placeholder="e.g. On-call covered by Sam" autocomplete="off"></div>
    <div class="err" id="logErr"></div>
    <div class="dlg-actions">
      <div class="right">
        <button class="btn ghost" value="cancel" formnovalidate>Cancel</button>
        <button class="btn" value="again">Save and add another</button>
        <button class="btn primary" value="save">Log time off</button>
      </div>
    </div>
  </form>
</dialog>
<dialog id="loginDlg">
  <form method="dialog" id="loginForm">
    <h3 id="loginTitle">Add a person</h3>
    <div class="field"><label for="uName">Name</label><input id="uName" maxlength="80" autocomplete="off" required></div>
    <div class="field"><label for="uEmail">Microsoft work email</label><input id="uEmail" type="email" maxlength="120" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="name@lesterglenn.com" required>
      <small>The address they use to sign in to Outlook and Teams.</small></div>
    <div class="field"><label for="uRole">Access</label>
      <select id="uRole"><option value="staff">Staff: IT Schedule only</option><option value="manager">Manager: IT Schedule and Time Off</option></select></div>
    <div class="err" id="loginErr"></div>
    <div class="dlg-actions"><div class="right">
      <button class="btn ghost" value="cancel" formnovalidate>Cancel</button>
      <button class="btn primary" value="save">Save</button>
    </div></div>
  </form>
</dialog>

<dialog id="rtoDlg" class="rto-dlg">
  <form method="dialog" id="rtoForm" autocomplete="off">
    <div class="rto-head"><img src="data:image/png;base64," alt="Lester Glenn Auto Group" width="188" height="88"><h3>Request for Time Off</h3></div>
    <div class="rto-grid">
      <label>Name<input id="rtoName" maxlength="80"></label>
      <label>Date<input id="rtoDate" type="date"></label>
      <label>Department<select id="rtoDept"><option value="">Choose…</option><option>Finance</option><option>Sales</option><option>Sales BDC</option><option>Service</option><option>Service BDC</option><option>Marketing</option><option>IT Dept</option><option>Corporate</option><option>Warranty</option><option>Shop</option><option>Parts</option></select></label>
      <fieldset class="rto-inline"><legend>Status</legend><label><input type="radio" name="rtoStatus" value="Full Time"> Full Time</label><label><input type="radio" name="rtoStatus" value="Part Time"> Part Time</label></fieldset>
      <label class="span2">Manager’s Name<input id="rtoMgr" list="rtoMgrList" maxlength="80"><datalist id="rtoMgrList"></datalist></label>
      <div class="span2 rto-dates"><span class="lbl">Requested Date(s) Off</span>
        <div><input id="rtoFrom" type="date" aria-label="First day off"><span>to</span><input id="rtoTo" type="date" aria-label="Last day off"><small id="rtoDays"></small></div>
        <input id="rtoDatesText" maxlength="200" placeholder="Or describe the dates, e.g. Mon 11/10 and Wed 11/12 mornings"></div>
      <label class="span2">Signature of Employee<input id="rtoSig" class="rto-sig" maxlength="80" placeholder="Type your full name to sign"></label>
      <label>Employee Initials<input id="rtoInit" maxlength="6"><small>(digitally signed above)</small></label>
      <fieldset class="rto-inline"><legend>Requesting time to be deducted from</legend><label><input type="radio" name="rtoDeduct" value="Personal"> Personal</label><label><input type="radio" name="rtoDeduct" value="Vacation"> Vacation</label></fieldset>
    </div>
    <fieldset class="rto-mgr" id="rtoMgrPart"><legend>Manager use</legend>
      <div class="rto-grid">
        <label>Date Received by Mgr<input id="rtoRecv" type="date"></label>
        <label>Calendar Checked<input id="rtoCal" type="date"></label>
        <fieldset class="rto-inline span2"><legend>Calendar</legend><label><input type="radio" name="rtoConflict" value="No Conflict"> No Conflict</label><label><input type="radio" name="rtoConflict" value="Conflict"> Conflict</label>
          <button class="btn small" id="rtoCheck" type="button">Check the calendar</button><small id="rtoCheckNote"></small></fieldset>
        <fieldset class="rto-inline span2"><legend>Decision</legend><label><input type="radio" name="rtoDecision" value="Approved"> Manager’s Approval</label><label><input type="radio" name="rtoDecision" value="Denied"> Manager’s Denial</label></fieldset>
        <label class="span2">Reason for Denial<input id="rtoReason" maxlength="200"></label>
      </div>
      <div class="rto-sub">Payroll use only</div>
      <div class="rto-grid">
        <fieldset class="rto-inline"><legend>Absence</legend><label><input type="radio" name="rtoPaid" value="Paid Absences"> Paid Absences</label><label><input type="radio" name="rtoPaid" value="Unpaid Absences"> Unpaid Absences</label></fieldset>
        <fieldset class="rto-inline"><legend>If paid, deduct from</legend><label><input type="radio" name="rtoPayDeduct" value="Personal"> Personal</label><label><input type="radio" name="rtoPayDeduct" value="Vacation"> Vacation</label></fieldset>
        <label>Manager’s Signature<input id="rtoMgrSig" class="rto-sig" maxlength="80" placeholder="Manager types full name"></label>
        <label>Date<input id="rtoMgrDate" type="date"></label>
      </div>
    </fieldset>
    <p class="rto-note">*Completed form gets emailed to <b>payroll@lesterglenn.com</b> by the manager with employee’s name and “RTO” in subject line.</p>
    <div class="err" id="rtoErr"></div>
    <div class="dlg-actions">
      <button class="btn" id="rtoDownload" type="button">⬇ Download copy</button>
      <div class="right">
        <button class="btn ghost" value="cancel" type="button">Cancel</button>
        <button class="btn" id="rtoPayroll" type="button" hidden>✉ Email Payroll</button>
        <button class="btn primary" id="rtoEmail" type="button">✉ Email My Managers</button>
      </div>
    </div>
  </form>
</dialog>

<div class="toast" id="toast" role="status"></div>
<script src="/app.js"></script>
</body>
</html>
